const input = $input.first().json;
const payload = input.body ?? input;
const event = payload.event ?? payload;
const ticket = event.ticket ?? {};
const customer = event.customer ?? event.contact ?? {};
const eventType = event.eventType ?? event.type;
if (eventType !== 'ticket.closed') throw new Error('Esperado evento ticket.closed');
const companyId = event.companyId ?? ticket.companyId;
const ticketId = event.ticketId ?? ticket.id;
const integrationId = event.integrationId ?? ticket.integrationId;
const customerId = event.customerId ?? customer.id ?? ticket.customerId;
const phone = customer.phone ?? event.phone ?? event.contact?.phone;
if (!event.eventId || !companyId || !ticketId || !integrationId || !customerId || !phone) throw new Error('Evento ticket.closed sem eventId, companyId, ticketId, integrationId, customerId ou telefone');
return [{ json: { eventId: event.eventId, companyId, ticketId, integrationId, customerId, phone: String(phone) } }];

const data = $input.first().json;
const idempotencyKey = 'nps:ticket:' + data.ticketId;
return [{ json: {
  ...data,
  idempotencyKey,
  outgoingText: 'Em uma escala de 0 a 10, o quanto você recomendaria nosso atendimento? Responda apenas com uma nota de 0 a 10. Obrigado!',
} }];
